 "content": "def transform(grid):
    """Complete the broken horizontal bars and project their colors up the marker columns."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])

    # Horizontal bars contain repeated colors separated by single-cell gaps.
    horizontal_rows = []
    for r, row in enumerate(out):
        if sum(v != 0 for v in row) >= 3:
            horizontal_rows.append(r)
            for c in range(1, w - 1):
                if row[c] == 0 and row[c - 1] != 0 and row[c - 1] == row[c + 1]:
                    row[c] = row[c - 1]

    # Sparse vertical marker(s) occupy columns with cells at the bottom of the grid.
    marker_cols = [c for c in range(w) if any(out[r][c] != 0 for r in range(max(0, h - 4), h))]
    for c in marker_cols:
        marker_rows = [r for r in range(h) if out[r][c] != 0 and r not in horizontal_rows]
        if not marker_rows:
            continue
        marker_color = out[max(marker_rows)][c]

        # Each horizontal bar that crosses this column gives the color of the
        # vertical segment above it, up to the preceding crossing.
        crossings = [(r, out[r][c]) for r in horizontal_rows if out[r][c] != 0]
        crossings.sort()
        if crossings:
            first_r, first_color = crossings[0]
            for r in range(first_r + 1):
                out[r][c] = first_color
            for (upper_r, _), (lower_r, lower_color) in zip(crossings, crossings[1:]):
                for r in range(upper_r + 1, lower_r + 1):
                    out[r][c] = lower_color
            last_r = crossings[-1][0]
        else:
            last_r = -1

        # The marker color fills the vertical tail below the final horizontal bar.
        for r in range(last_r + 1, h):
            out[r][c] = marker_color

    return out
